#include <stdio.h>

#define MAXV 100
#define MAXE 200

int head[MAXV];
int to[2 * MAXE];
int nxt[2 * MAXE];
int ecnt = 0;

void add(int u, int v) {
    to[ecnt] = v;
    nxt[ecnt] = head[u];
    head[u] = ecnt++;
}

int main(void) {
    for (int i = 0; i < MAXV; i++) head[i] = -1;
    int V = 5;

    /* 无向图：每条边存两次 */
    add(0,1); add(1,0);
    add(0,2); add(2,0);
    add(1,3); add(3,1);
    add(2,3); add(3,2);
    add(3,4); add(4,3);

    printf("邻接表（头插法，故邻接点顺序与插入顺序相反）：\n");
    for (int u = 0; u < V; u++) {
        int deg = 0;
        printf("%d -> ", u);
        for (int e = head[u]; e != -1; e = nxt[e]) { printf("%d ", to[e]); deg++; }
        printf("  出度=%d\n", deg);
    }

    printf("\n边节点总数 = %d（无向图每条边存两次，故为 2E）\n", ecnt);
    printf("空间占用（已用部分）= (V + 2*E) * sizeof(int) = (%d + %d) * %zu = %zu 字节\n",
           V, ecnt, sizeof(int), (size_t)(V + 2 * ecnt) * sizeof(int));

    printf("\n与矩阵对比：本例 V=5，矩阵需 %zu 字节，邻接表仅 %zu 字节\n",
           (size_t)(5 * 5 * sizeof(int)), (size_t)(V + 2 * ecnt) * sizeof(int));
    printf("但判边 (0,3) 需要遍历 0 的邻接链 —— 这是邻接表的短板 O(deg)\n");
    return 0;
}
